template<class T> inline void construct(T *p, const T& value) { new ((void*)p) T(value); }
template<class T> inline void destroy(T *p) { p->~T(); }
template<class T> inline void destroy(T *first, T *last) { while (first != last) { destroy(first); ++first; } }
template<class T> T *uninitialized_copy(T *first, T *last, T *result) { T *cur=result; while(first!=last) { construct(cur,*first); ++first; ++cur; } return cur; }
template<class T> T *uninitialized_fill_n(T *first, unsigned int n, const T& value) { T *cur=first; while(n) { construct(cur,value); ++cur; --n; } return cur; }
template<class T> T *copy_backward(T *first, T *last, T *result) { while(first!=last) { --result; --last; *result=*last; } return result; }
template<class T> void fill(T *first, T *last, const T& value) { while(first!=last) { *first=value; ++first; } }
template<class T> inline const T& max(const T& a,const T& b) { return a<b?b:a; }
